import { BOTAO_PRIMARIO, BOTAO_SECUNDARIO, BOTAO_LINK } from '../../componentes/campos.jsx'

/**
 * Padrão de tela do admin: lista à esquerda do tempo, formulário quando um item
 * está selecionado ou sendo criado. Quem usa fornece `renderLinha` e `renderFormulario`.
 */
export function Lista({ itens, chave, renderLinha, onSelecionar, selecionadoId, rotuloNovo, onNovo, cabecalho }) {
  return (
    <div>
      <div className="flex items-center justify-between mb-3">
        <span className="text-[12px] font-extrabold uppercase tracking-[.08em] text-mudo">{cabecalho}</span>
        <button onClick={onNovo} className={BOTAO_SECUNDARIO}>{rotuloNovo}</button>
      </div>
      <ul className="divide-y divide-fio border-y-2 border-tinta">
        {itens.map((item) => {
          const id = chave(item)
          const ativo = id === selecionadoId
          return (
            <li key={id}>
              <button
                onClick={() => onSelecionar(id)}
                className={'w-full text-left px-3 py-3 text-[13.5px] hover:bg-areia transition-colors relative ' + (ativo ? 'bg-areia' : '')}
              >
                {renderLinha(item)}
              </button>
            </li>
          )
        })}
      </ul>
    </div>
  )
}

export function Formulario({ titulo, onSalvar, onCancelar, onExcluir, podeSalvar = true, children }) {
  return (
    <form
      onSubmit={(e) => { e.preventDefault(); if (podeSalvar) onSalvar() }}
      className="bg-areia p-6 space-y-5"
    >
      <h3 className="display text-[20px]">{titulo}</h3>
      {children}
      <div className="flex items-center justify-between pt-4 border-t-2 border-tinta">
        <span className="flex items-center gap-4">
          <button type="button" onClick={onCancelar} className={BOTAO_LINK}>Cancelar</button>
          {onExcluir && (
            <button type="button" onClick={onExcluir} className={BOTAO_LINK + ' underline underline-offset-4'}>Excluir</button>
          )}
        </span>
        <button type="submit" disabled={!podeSalvar} className={BOTAO_PRIMARIO}>Salvar</button>
      </div>
    </form>
  )
}

export function novoId(prefixo) {
  return `${prefixo}_${Date.now().toString(36)}`
}
