import { useState } from 'react'
import { formatarData } from '../../regras/datas.js'

const ROTULO = { enviado: 'enviado', simulado: 'simulado', pulado: 'pulado', erro: 'erro' }

/**
 * Operação do LOMBADA: e-mail da segunda (ActiveCampaign), sincronização de aulas e o registro do que rodou.
 * `operacao` vem do AdminNuvem; no protótipo local não existe e a aba explica isso.
 */
export default function AdminOperacao({ operacao }) {
  const [msg, setMsg] = useState('')
  const [ocupado, setOcupado] = useState('')
  const [resultado, setResultado] = useState(null)
  if (!operacao) return <p className="text-[14px] text-apoio">A operação (e-mail semanal, aulas, envios) só existe na nuvem. Abra o Admin publicado.</p>

  const { config = {}, envios = [], aulasEm } = operacao
  const envioAtivo = config.envio_ativo === 'true'
  const ultimoEnvio = envios.find((e) => e.canal === 'activecampaign')
  const rodadas = agruparRodadas(envios)

  async function rodar(nome, fn) {
    setOcupado(nome); setMsg(''); setResultado(null)
    try { const r = await fn(); setResultado(r); setMsg('Feito.') } catch (e) { setMsg(e.message) } finally { setOcupado('') }
  }

  return (
    <div className="grid gap-6">
      <section className="bg-areia p-5 sm:p-6 corte-d">
        <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo">E-mail da segunda-feira</p>
        <h2 className="display text-[24px] mt-1">{envioAtivo ? 'Envio LIGADO' : 'Envio DESLIGADO (só simula)'}</h2>
        <p className="text-[13.5px] text-apoio mt-2 max-w-[62ch]">
          Toda segunda às 7h o LOMBADA calcula a semana de cada autor e grava no ActiveCampaign (lista LOMBADA - Autores, tag lombada-semana).
          Quem envia o e-mail é a automação do ActiveCampaign. Enquanto estiver desligado, só registra o que teria saído.
        </p>
        <div className="flex flex-wrap gap-2 mt-4">
          <button onClick={() => rodar('toggle', () => operacao.definirConfig('envio_ativo', envioAtivo ? 'false' : 'true'))} disabled={!!ocupado} className={envioAtivo ? 'btn-linha' : 'btn-primario'}>
            {envioAtivo ? 'Desligar envio' : 'Ligar envio'}
          </button>
          <button onClick={() => rodar('simular', () => operacao.simular())} disabled={!!ocupado} className="btn-preto">{ocupado === 'simular' ? 'Simulando…' : 'Simular agora'}</button>
          {envioAtivo && <button onClick={() => { if (window.confirm('Enviar a semana AGORA para todos os autores elegíveis? Isso marca a tag no ActiveCampaign e dispara o e-mail.')) rodar('enviar', () => operacao.enviarAgora()) }} disabled={!!ocupado} className="btn-linha">{ocupado === 'enviar' ? 'Enviando…' : 'Enviar agora'}</button>}
        </div>
        <p className="text-[12px] text-mudo mt-3">Link enviado aos autores: <b className="text-tinta">{config.url_app || '—'}</b> · Último registro: {ultimoEnvio ? `${formatarData(ultimoEnvio.criado_em)} (${ROTULO[ultimoEnvio.status] || ultimoEnvio.status})` : 'nenhum ainda'}</p>
        {msg && <p className="text-[13px] font-bold mt-2">{msg}</p>}
        {resultado?.resultados && (
          <div className="mt-4 bg-white p-4 text-[13px]">
            <p className="font-bold mb-2">{resultado.dry ? 'Simulação' : 'Envio'}: {resultado.total} autores · {resultado.enviados} enviados · {resultado.erros} erros</p>
            <ul className="grid gap-1">
              {resultado.resultados.map((r) => (
                <li key={r.email} className="flex flex-wrap gap-x-2">
                  <span className={'font-extrabold uppercase text-[10px] tracking-[.1em] self-center px-1.5 py-0.5 ' + (r.status === 'enviado' ? 'bg-verde text-white' : r.status === 'simulado' ? 'bg-ambar' : r.status === 'erro' ? 'bg-alerta text-white' : 'bg-areia')}>{r.status}</span>
                  <span className="font-bold">{r.nome || r.email}</span>
                  <span className="text-apoio">{r.motivo ? `(${r.motivo})` : `${r.acoes} ações · ${r.situacao} · próxima: ${r.proxima || '—'}`}</span>
                </li>
              ))}
            </ul>
          </div>
        )}
      </section>

      <section className="bg-areia p-5 sm:p-6 corte-d">
        <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo">Aulas da área de membros</p>
        <h2 className="display text-[24px] mt-1">Sincronização automática</h2>
        <p className="text-[13.5px] text-apoio mt-2 max-w-[62ch]">Todo dia às 6h o LOMBADA lê os módulos e aulas da Hotmart e marca as novas. Última leitura: <b className="text-tinta">{aulasEm ? formatarData(aulasEm) : 'ainda não rodou'}</b>.</p>
        <button onClick={() => rodar('aulas', () => operacao.sincronizarAulas())} disabled={!!ocupado} className="btn-preto mt-4">{ocupado === 'aulas' ? 'Lendo a Hotmart…' : 'Sincronizar agora'}</button>
        {resultado?.modulos !== undefined && <p className="text-[13px] mt-3">{resultado.modulos} módulos · {resultado.aulas} aulas · novas: {resultado.novas?.length || 0}</p>}
      </section>

      <section>
        <h2 className="display text-[22px]">Últimas rodadas</h2>
        {rodadas.length === 0 ? <p className="text-[13.5px] text-apoio mt-2">Nada registrado ainda. A primeira rodada é na próxima segunda às 7h, ou agora pelo botão Simular.</p> : (
          <div className="overflow-x-auto mt-3">
            <table className="w-full text-[13px]">
              <thead><tr className="text-left text-[11px] font-extrabold uppercase tracking-[.1em] text-mudo border-b-2 border-tinta"><th className="py-2 pr-3">Semana</th><th className="py-2 pr-3">Quando</th><th className="py-2 pr-3">Enviados</th><th className="py-2 pr-3">Simulados</th><th className="py-2 pr-3">Pulados</th><th className="py-2 pr-3">Erros</th></tr></thead>
              <tbody>{rodadas.map((r) => (
                <tr key={r.chave} className="border-b border-fio"><td className="py-2 pr-3 font-bold">{formatarData(r.semana)}</td><td className="py-2 pr-3">{formatarData(r.quando)}</td><td className="py-2 pr-3">{r.enviado || 0}</td><td className="py-2 pr-3">{r.simulado || 0}</td><td className="py-2 pr-3">{r.pulado || 0}</td><td className="py-2 pr-3">{r.erro || 0}</td></tr>
              ))}</tbody>
            </table>
          </div>
        )}
      </section>
    </div>
  )
}

/** Agrupa os registros por rodada (mesma semana, mesmo minuto). */
function agruparRodadas(envios) {
  const mapa = new Map()
  for (const e of envios) {
    if (e.canal !== 'activecampaign') continue
    const chave = `${e.semana}|${String(e.criado_em).slice(0, 16)}`
    const r = mapa.get(chave) || { chave, semana: e.semana, quando: e.criado_em }
    r[e.status] = (r[e.status] || 0) + 1
    mapa.set(chave, r)
  }
  return [...mapa.values()].slice(0, 12)
}
